      name: 'users_get_many',
      description: 'Look up multiple users by id, returning one line per requested id in request order. Missing users are marked without failing the batch.',
      inputSchema: {
        type: 'object',
        properties: {
          user_ids: {
            type: 'array',
            items: { type: 'string' },
            minItems: 1,
            maxItems: 5,
            uniqueItems: true
          }
        },
        required: ['user_ids'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'users_get_many') {
    throw new Error('Unknown tool: ' + name);
  }
  // Reject extra fields
  const keys = Object.keys(args);
  if (keys.length !== 1 || keys[0] !== 'user_ids') {
    throw new Error('Unexpected fields; expected only user_ids');
  }
  const user_ids = args.user_ids;
  // Must be an array
  if (!Array.isArray(user_ids)) {
    throw new Error('user_ids must be an array');
  }
  // Non-empty
