    throw new Error('user_ids must not be empty');
  }
  // At most 5
  if (user_ids.length > 5) {
    throw new Error('user_ids must have at most 5 entries');
  }
  // All strings
  for (const id of user_ids) {
    if (typeof id !== 'string') {
      throw new Error('user_ids must contain only strings');
    }
  }
  // Unique
  const seen = new Set();
  for (const id of user_ids) {
    if (seen.has(id)) {
      throw new Error('user_ids must not contain duplicates');
    }
    seen.add(id);
  }
  const lines = user_ids.map(id => {
    const user = users[id];
    if (user) {
      return `${id}: ${user.name}`;
    }
    return `${id}: not found`;
  });
  return { content: [{ type: 'text', text: lines.join('\n') }] };
}
